// send_confirmation — Validate Input
// Expected body: { business_id, booking_id, customer_name, customer_phone,
//   service, appointment_start, appointment_label }
const body = $input.first().json.body || {};

const businessId = String(body.business_id ?? '').trim();
const bookingId = String(body.booking_id ?? '').trim();
const customerName = String(body.customer_name ?? body.name ?? '').trim();
const customerPhone = String(body.customer_phone ?? body.phone ?? '').trim();
const service = String(body.service ?? body.service_name ?? '').trim();
const startTime = String(body.appointment_start ?? body.start_time ?? '').trim();
const providedLabel = String(body.appointment_label ?? '').trim();

const errors = [];
if (!businessId) errors.push('business_id is required');
if (!bookingId) errors.push('booking_id is required');
if (!customerName) errors.push('customer_name is required');
if (!customerPhone) errors.push('customer_phone is required');
if (!service) errors.push('service is required');

let start = null;
if (!startTime) {
  errors.push('appointment_start is required');
} else {
  start = DateTime.fromISO(startTime, { setZone: true });
  if (!start.isValid) errors.push('appointment_start must be a valid ISO 8601 date and time');
}

return [{
  json: {
    valid: errors.length === 0,
    errors,
    business_id_input: businessId,
    booking_id: bookingId,
    customer_name: customerName,
    customer_phone: customerPhone,
    service,
    appointment_start: start && start.isValid ? start.toISO() : null,
    appointment_label_provided: providedLabel || null,
  },
}];

// Normalize Business
const items = $input.all();
const row = items[0] && items[0].json && items[0].json.id ? items[0].json : null;

return [{
  json: {
    business_found: !!row,
    business_name: row ? row.name : null,
    business_timezone: row ? row.timezone : null,
  },
}];

// send_confirmation — Build Message
const input = $('Validate Input').first().json;
const business = $('Normalize Business').first().json;

const label =
  input.appointment_label_provided ||
  (input.appointment_start
    ? DateTime.fromISO(input.appointment_start, { setZone: true })
        .setZone(business.business_timezone || 'UTC')
        .toFormat("cccc, LLLL d 'at' h:mm a")
    : input.appointment_start);

const messageText =
  business.business_name + ': Hi ' + input.customer_name + ", you're booked for " + input.service +
  ' on ' + label + '. Call us back if you need to change anything.';

return [{ json: { message_text: messageText, appointment_label: label } }];

// send_confirmation — Build Response
// The Twilio node is a placeholder: no credential, no From number, and
// runs with onError = continueRegularOutput. Until a real Twilio account
// is wired up it fails on every call and lands here as an item carrying
// an `error`, reported honestly as not_sent rather than dressed up as a
// success.
const item = $input.first();
const failed = !!(item && item.json && item.json.error);

const input = $('Validate Input').first().json;
const built = $('Build Message').first().json;

return [{
  json: {
    booking_id: input.booking_id,
    business_id: input.business_id_input,
    status: failed ? 'not_sent' : 'sent',
    sent: !failed,
    channel: 'sms',
    to: input.customer_phone,
    message_text: built.message_text,
    detail: failed
      ? 'Twilio is not configured yet, so no SMS was sent. The booking itself is unaffected. See docs/n8n-setup.md.'
      : 'Confirmation SMS handed to Twilio.',
  },
}];
